package net.civeira.phylax.features.access.userfederatedidentity.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.access.tenantloginprovider.domain.TenantLoginProviderReference;
import net.civeira.phylax.features.access.user.domain.UserReference;

class UserFederatedIdentityFilterUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_user_federated_identity_filter_builder() {
    UserFederatedIdentityFilter filter = UserFederatedIdentityFilter.builder().build();
    Assertions.assertFalse(filter.getUid().isPresent(),
        "Uid must be empty if filter is build without it");
    filter.setUid("one");
    Assertions.assertEquals("one", filter.getUid().get(), "Uid must be the same as the assigned");
    Assertions.assertTrue(filter.getUids().isEmpty(),
        "Uid must be empty if filter is build without it");
    filter.setUids(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUids(),
        "Uids must be the same as the assigned");
    Assertions.assertFalse(filter.getSearch().isPresent(),
        "Search must be empty if filter is build without it");
    filter.setSearch("lookup");
    Assertions.assertEquals("lookup", filter.getSearch().get(),
        "Search must be the same as the assigned");
    Assertions.assertFalse(filter.getSubject().isPresent(),
        "Subject must be empty if filter is build without it");
    filter.setSubject("one");
    Assertions.assertEquals("one", filter.getSubject().get(),
        "Subject must be the same as the assigned");
    Assertions.assertFalse(filter.getUser().isPresent(),
        "User must be empty if filter is build without it");
    filter.setUser(UserReference.of("$ref"));
    Assertions.assertEquals(UserReference.of("$ref"), filter.getUser().get(),
        "User must be the same as the assigned");
    Assertions.assertTrue(filter.getUsers().isEmpty(),
        "Users must be empty if filter is build without it");
    filter.setUsers(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUsers(),
        "Users must be the same as the assigned");
    Assertions.assertFalse(filter.getLoginProvider().isPresent(),
        "LoginProvider must be empty if filter is build without it");
    filter.setLoginProvider(TenantLoginProviderReference.of("$ref"));
    Assertions.assertEquals(TenantLoginProviderReference.of("$ref"),
        filter.getLoginProvider().get(), "LoginProvider must be the same as the assigned");
    Assertions.assertTrue(filter.getLoginProviders().isEmpty(),
        "LoginProviders must be empty if filter is build without it");
    filter.setLoginProviders(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getLoginProviders(),
        "LoginProviders must be the same as the assigned");
    Assertions.assertFalse(filter.getUserTenantAccessible().isPresent(),
        "UserTenantAccessible must be empty if filter is build without it");
    filter.setUserTenantAccessible("one");
    Assertions.assertEquals("one", filter.getUserTenantAccessible().get(),
        "UserTenantAccessible must be the same as the assigned");
  }

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test the filter of a unique index")
  void test_user_federated_identity_filter_by_login_provider_and_subject() {
    UserFederatedIdentityFilter filter = UserFederatedIdentityFilter
        .byLoginProviderAndSubject(TenantLoginProviderReference.of("$ref"), "one");
    Assertions.assertEquals(TenantLoginProviderReference.of("$ref"),
        filter.getLoginProvider().orElse(null),
        "LoginProvider must be the one of the unique index");
    Assertions.assertEquals("one", filter.getSubject().orElse(null),
        "Subject must be the one of the unique index");
  }
}
